117	// refreshCacheIfStale checks whether the insights cache is up-to-date with the
118	// entire/checkpoints/v1 branch and rebuilds it if not.
119	func refreshCacheIfStale(ctx context.Context, idb *insightsdb.InsightsDB) error {
120		repo, err := openRepository(ctx)
121		if err != nil {
122			return fmt.Errorf("open git repository: %w", err)
123		}
124	
125		// Resolve the current tip of entire/checkpoints/v1.
126		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
127		ref, resolveErr := repo.Reference(refName, true)
128		if resolveErr != nil {
129			// Branch doesn't exist yet — nothing to cache.
130			return nil //nolint:nilerr // Missing branch is expected, not an error
131		}
132		currentTip := ref.Hash().String()
133	
134		cachedTip, err := idb.GetBranchTip(ctx)
135		if err != nil {
136			return fmt.Errorf("get cached branch tip: %w", err)
137		}
138	
139		if cachedTip == currentTip {
140			return nil // Cache is up-to-date.
141		}
142	
143		// Cache is stale — rebuild from git.
144		store := checkpoint.NewGitStore(repo)
145		committedList, err := store.ListCommitted(ctx)
146		if err != nil {
147			return fmt.Errorf("list committed checkpoints: %w", err)
148		}
149	
150		for _, info := range committedList {
151			cpIDStr := info.CheckpointID.String()
152	
153			// Check whether we already have this checkpoint cached.
154			has, hasErr := idb.HasCheckpoint(ctx, cpIDStr)
155			if hasErr != nil {
156				return fmt.Errorf("check checkpoint %s: %w", cpIDStr, hasErr)
157			}
158			if has {
159				continue
160			}
161	
162			// Read the checkpoint summary to find how many sessions it has.
163			summary, readErr := store.ReadCommitted(ctx, info.CheckpointID)
164			if readErr != nil {
165				continue // Skip unreadable checkpoints; don't abort the whole refresh.
166			}
167	
168			for i := range summary.Sessions {
169				content, contentErr := store.ReadSessionContent(ctx, info.CheckpointID, i)
170				if contentErr != nil {
171					continue
172				}
173				row := metadataToSessionRow(cpIDStr, i, &content.Metadata)
174				row.ToolCounts = extractToolCounts(content.Transcript, content.Metadata.Agent)
175				if insertErr := idb.InsertSession(ctx, row); insertErr != nil {
176					return fmt.Errorf("insert session %s/%d: %w", cpIDStr, i, insertErr)
177				}
178			}
179		}
180	
181		if err := idb.SetBranchTip(ctx, currentTip); err != nil {
182			return fmt.Errorf("set branch tip: %w", err)
183		}
184		return nil
185	}
